'use strict';
const $=id=>document.getElementById(id);
const state={mode:'swipe',view:'compare',split:.5,zoom:1,x:0,y:0,blink:0,timer:null,images:[],meta:null,a:0,b:1};
const canvas=$('skyCanvas'),ctx=canvas.getContext('2d');let W=1,H=1,aladin=null,skyLoading=false;
function status(text){$('status').textContent=text;$('status').hidden=!text;}
function resize(){const r=canvas.getBoundingClientRect();if(!r.width)return;W=r.width;H=r.height;canvas.width=W*devicePixelRatio;canvas.height=H*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);draw();}
new ResizeObserver(resize).observe($('viewer'));
function frame(index,x,y,w,h){const im=state.images[index];if(!im)return;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();const s=Math.max(w/im.width,h/im.height)*state.zoom,iw=im.width*s,ih=im.height*s;const ix=x+(w-iw)/2+state.x,iy=y+(h-ih)/2+state.y;ctx.imageSmoothingEnabled=false;ctx.drawImage(im,ix,iy,iw,ih);if($('markers').checked){const m=state.meta.observations[index].marker;const px=ix+m[0]*iw,py=iy+m[1]*ih;ctx.strokeStyle='#b9f5ce';ctx.lineWidth=1;ctx.beginPath();ctx.arc(px,py,13,0,Math.PI*2);ctx.stroke();ctx.fillStyle='#c6ffd9';ctx.font='12px sans-serif';ctx.fillText('3I/ATLAS · predicted',px+19,py-9);}ctx.restore();}
function draw(){ctx.fillStyle='#030609';ctx.fillRect(0,0,W,H);if(!state.images.length)return;if(state.mode==='split'){frame(state.a,0,0,W/2,H);frame(state.b,W/2,0,W/2,H);}else if(state.mode==='blink'){frame(state.blink?state.b:state.a,0,0,W,H);}else{frame(state.b,0,0,W,H);ctx.save();ctx.beginPath();ctx.rect(0,0,W*state.split,H);ctx.clip();frame(state.a,0,0,W,H);ctx.restore();}$('divider').hidden=state.mode!=='swipe';$('divider').style.left=state.split*100+'%';$('tagA').hidden=state.mode==='blink'&&!!state.blink;$('tagB').hidden=state.mode==='blink'&&!state.blink;}
function stop(){clearInterval(state.timer);state.timer=null;$('play').textContent='▶ Play blink comparison';}
function mode(m){stop();state.mode=m;document.querySelectorAll('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));$('swipeControl').hidden=m!=='swipe';draw();}
document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>mode(b.dataset.mode));
$('slider').oninput=e=>{state.split=e.target.value/100;$('percent').textContent=e.target.value+'%';draw();};
$('play').onclick=()=>{if(state.timer){stop();return;}mode('blink');$('play').textContent='Ⅱ Pause blink comparison';state.timer=setInterval(()=>{state.blink=1-state.blink;draw();},800);};
$('markers').onchange=draw;
function zoom(f){state.zoom=Math.min(8,Math.max(1,state.zoom*f));if(state.zoom===1)state.x=state.y=0;draw();}
$('zoomIn').onclick=()=>zoom(1.3);$('zoomOut').onclick=()=>zoom(1/1.3);$('reset').onclick=()=>{state.zoom=1;state.x=state.y=0;draw();};
canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(e.deltaY<0?1.12:1/1.12);},{passive:false});let drag=null;
canvas.onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,swipe:state.mode==='swipe'&&Math.abs(e.offsetX-W*state.split)<25};canvas.setPointerCapture(e.pointerId);};
canvas.onpointermove=e=>{if(!drag)return;if(drag.swipe){state.split=Math.min(1,Math.max(0,e.offsetX/W));$('slider').value=state.split*100;$('percent').textContent=Math.round(state.split*100)+'%';}else{state.x+=e.clientX-drag.x;state.y+=e.clientY-drag.y;}drag.x=e.clientX;drag.y=e.clientY;draw();};canvas.onpointerup=canvas.onpointercancel=()=>drag=null;
canvas.onkeydown=e=>{if(['+','=','-','ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))e.preventDefault();if(e.key==='+'||e.key==='=')zoom(1.3);if(e.key==='-')zoom(1/1.3);if(e.key==='ArrowLeft')state.x+=25;if(e.key==='ArrowRight')state.x-=25;if(e.key==='ArrowUp')state.y+=25;if(e.key==='ArrowDown')state.y-=25;draw();};
function updateEpochs(){state.a=Number($('epochA').value);state.b=Number($('epochB').value);const a=state.meta.observations[state.a],b=state.meta.observations[state.b];$('tagA').textContent='A · '+a.label;$('tagB').textContent='B · '+b.label;const minutes=Math.round(Math.abs(Date.parse(b.utc)-Date.parse(a.utc))/60000);$('interval').textContent=minutes?`${Math.floor(minutes/60)} h ${minutes%60} min between exposures · UTC`:'Same exposure selected · no time difference';draw();}
function view(name){stop();state.view=name;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));$('compareControls').hidden=name!=='compare';$('skyControls').hidden=name!=='sky';$('comparison').hidden=name!=='compare';$('aladin').hidden=name!=='sky';$('viewTitle').textContent=name==='compare'?'Follow the change.':'Find your place in the universe.';$('viewEyebrow').textContent=name==='compare'?'SPHEREx / TIME DOMAIN':'ALL-SKY / REFERENCE ATLAS';$('dataTag').textContent=name==='compare'?'ARCHIVAL OBSERVATIONS':'2MASS / DSS2 REFERENCE';status('');if(name==='sky')initSky();else {if(state.meta){$('position').textContent=`ICRS · RA ${state.meta.center[0].toFixed(4)}° / Dec ${state.meta.center[1].toFixed(4)}°`;$('fieldSize').textContent=`${state.meta.fov}° field · North up / East left`;}if(!state.meta)status('SPHEREx images could not load. Refresh to retry.');resize();}}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));$('comet').onclick=()=>view('compare');
async function initSky(){if(aladin)return;if(skyLoading)return;skyLoading=true;status('Connecting to the CDS sky atlas…');try{if(!window.A)await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://aladin.cds.unistra.fr/AladinLite/api/v3/latest/aladin.js';s.onload=resolve;s.onerror=reject;document.head.append(s);});await A.init;aladin=A.aladin('#aladin',{survey:'P/2MASS/color',fov:4,target:'83.822 -5.391',showReticle:true,showCooGrid:false,showLayersControl:true,showFullscreenControl:true});aladin.on('positionChanged',p=>{$('position').textContent=`ICRS · RA ${p.ra.toFixed(4)}° / Dec ${p.dec.toFixed(4)}°`;});$('fieldSize').textContent='Reference sky · drag to explore';status('');}catch(e){status('The sky atlas is unavailable. Check your internet connection and reopen Sky map. The bundled SPHEREx comparison still works.');}finally{skyLoading=false;}}
$('targetSelect').onchange=e=>{if(aladin){const [ra,dec]=e.target.value.split(' ').map(Number);aladin.gotoRaDec(ra,dec);aladin.setFoV(4);}};$('survey').onchange=e=>{if(aladin)aladin.setImageSurvey(e.target.value);};$('coordinates').onsubmit=e=>{e.preventDefault();if(aladin)aladin.gotoRaDec(Number($('ra').value),Number($('dec').value));};
$('about').onclick=()=>$('mission').showModal();$('closeDialog').onclick=()=>$('mission').close();$('mission').onclick=e=>{if(e.target===$('mission'))$('mission').close();};document.addEventListener('visibilitychange',()=>{if(document.hidden)stop();});
async function init(){try{const response=await fetch('observations.json');if(!response.ok)throw Error('metadata');state.meta=await response.json();state.images=await Promise.all(state.meta.observations.map(o=>new Promise((resolve,reject)=>{let im=new Image();im.onload=()=>resolve(im);im.onerror=reject;im.src=o.image;})));for(const id of ['epochA','epochB'])state.meta.observations.forEach((o,i)=>{const opt=document.createElement('option');opt.value=i;opt.textContent=o.label+' UTC';$(id).append(opt);});$('epochB').value='1';$('epochA').onchange=$('epochB').onchange=updateEpochs;const m=state.meta;$('position').textContent=`ICRS · RA ${m.center[0].toFixed(4)}° / Dec ${m.center[1].toFixed(4)}°`;$('fieldSize').textContent=`${m.fov}° field · North up / East left`;$('provenance').textContent=m.processing;for(const o of m.observations){const p=document.createElement('p');const a=document.createElement('a');a.href=o.source;a.target='_blank';a.rel='noopener';a.textContent=o.id+' · '+o.label+' UTC · original FITS';p.append(a);$('provenance').append(p);}status('');updateEpochs();resize();}catch(e){status('Unable to load the observation pair. Refresh the page to retry, or explore the reference Sky map.');console.error(e);}}
init();
